{"summary": "Upload Property Documents", "description": "Attach legal or promotional documents to a property advertisement.", "parameters": [{"name": "property_id", "in": "path", "required": true, "description": "Unique identifier of the property.", "schema": {"type": "string"}}], "requestBody": {"required": true, "content": {"multipart/form-data": {"schema": {"type": "object", "properties": {"document": {"type": "string", "format": "binary", "description": "Document file."}}}}}}, "responses": {"201": {"description": "Document uploaded successfully."}}}

Endpoint: GET /tenant/credit-check/status/{tenantId}
Specification:
{"summary": "Retrieve tenant credit check status", "description": "Obtain the status and outcomes of a completed credit check for a specific tenant.", "parameters": [{"name": "tenantId", "in": "path", "required": true, "schema": {"type": "string"}, "description": "The unique identifier for the tenant."}], "responses": {"200": {"description": "Credit check status retrieved successfully.", "content": {"application/json": {"schema": {"type": "object", "properties": {"status": {"type": "string", "enum": ["Pending", "Completed", "Failed"], "description": "The status of the credit check."}, "creditScore": {"type": "integer", "description": "The tenant's credit score, if applicable."}}}}}}, "404": {"description": "Tenant not found or no credit check exists."}}}

Endpoint: PUT /settings/notifications
Specification:
{"summary": "Set notification preferences", "description": "Configure preferences to receive notifications for updates on identity, credit, or rental history verification checks.", "requestBody": {"required": true, "content": {"application/json": {"schema": {"type": "object", "properties": {"emailNotifications": {"type": "boolean", "description": "Enable or disable email notifications."}, "smsNotifications": {"type": "boolean", "description": "Enable or disable SMS notifications."}}, "required": ["emailNotifications", "smsNotifications"]}}}}, "responses": {"200": {"description": "Notification preferences updated successfully."}}}

Endpoint: DELETE /properties/{property_id}/photos/{photo_id}
Specification:
{"summary": "Delete Property Photo", "description": "Delete a specific photo from a property advertisement.", "parameters": [{"name": "property_id", "in": "path", "required": true, "description": "Unique identifier of the property.", "schema": {"type": "string"}}, {"name": "photo_id", "in": "path", "required": true, "description": "Unique identifier of the photo.", "schema": {"type": "string"}}], "responses": {"204": {"description": "Photo deleted successfully."}, "404": {"description": "Photo or property not found."}}}

Endpoint: PUT /properties/{property_id}
Specification:
{"summary": "Update Property Details", "description": "Update the details of an existing property advertisement.", "parameters": [{"name": "property_id", "in": "path", "required": true, "description": "Unique identifier of the property.", "schema": {"type": "string"}}], "requestBody": {"required": true, "content": {"application/json": {"schema": {"$ref": "#/components/schemas/Property"}}}}, "responses": {"200": {"description": "Property updated successfully.", "content": {"application/json": {"schema": {"$ref": "#/components/schemas/Property"}}}}, "404": {"description": "Property not found."}}}

Endpoint: GET /support/contact
Specification:
{"summary": "Retrieve support contact information", "description": "Fetch information about how to contact support for assistance with the service.", "responses": {"200": {"description": "Support contact information retrieved successfully."}}}

Endpoint: GET /documentation
Specification:
{"summary": "Retrieve API documentation", "description": "Retrieve detailed documentation for available API endpoints and their usage.", "responses": {"200": {"description": "API documentation retrieved successfully."}}}

Endpoint: POST /properties
Specification:
{"summary": "Create a New Property Advertisement", "description": "Create and post a new property advertisement.", "requestBody": {"required": true, "content": {"application/json": {"schema": {"$ref": "#/components/schemas/Property"}}}}, "responses": {"201": {"description": "Property advertisement created successfully.", "content": {"application/json": {"schema": {"$ref": "#/components/schemas/Property"}}}}}}

Endpoint: GET /properties/search
Specification:
{"summary": "Search Properties", "description": "Search properties based on specific criteria such as location and price range.", "parameters": [{"name": "location", "in": "query", "description": "Filter properties by location.", "schema": {"type": "string"}}, {"name": "price_min", "in": "query", "description": "Minimum price of the properties.", "schema": {"type": "integer"}}, {"name": "price_max", "in": "query", "description": "Maximum price of the properties.", "schema": {"type": "integer"}}], "responses": {"200": {"description": "Properties matching criteria retrieved successfully.", "content": {"application/json": {"schema": {"type": "array", "items": {"$ref": "#/components/schemas/Property"}}}}}}}

Endpoint: GET /properties/{property_id}
Specification:
{"summary": "Get Property Details", "description": "Retrieve detailed information about a specific property advertisement.", "parameters": [{"name": "property_id", "in": "path", "required": true, "description": "Unique identifier of the property.", "schema": {"type": "string"}}], "responses": {"200": {"description": "Property details retrieved successfully.", "content": {"application/json": {"schema": {"$ref": "#/components/schemas/Property"}}}}, "404": {"description": "Property not found."}}}

Endpoint: GET /rental-analysis
Specification:
{"summary": "Analyze rental market", "description": "Analyze dynamics in the rental market, including tenant demand and pricing trends.", "parameters": [{"name": "city", "in": "query", "required": true, "description": "City for rental analysis.", "schema": {"type": "string"}}], "responses": {"200": {"description": "Rental market analysis retrieved successfully.", "content": {"application/json": {"schema": {"type": "object"}}}}}}

Endpoint: POST /templates
Specification:
{"summary": "Upload a new template", "description": "Upload a new real estate document template for customization and use in property transactions.", "requestBody": {"required": true, "content": {"multipart/form-data": {"schema": {"type": "object", "properties": {"template_file": {"type": "string", "format": "binary", "description": "The file for the template being uploaded."}, "name": {"type": "string", "description": "The name of the template."}, "description": {"type": "string", "description": "A brief description of the template."}}, "required": ["template_file", "name"]}}}}, "responses": {"201": {"description": "Template uploaded successfully.", "content": {"application/json": {"schema": {"type": "object", "properties": {"template_id": {"type": "string", "description": "Unique identifier for the uploaded template."}}}}}}}}

Endpoint: PUT /documents/{document_id}
Specification:
{"summary": "Update a document", "description": "Update an existing document with new information or changes.", "parameters": [{"name": "document_id", "in": "path", "required": true, "schema": {"type": "string"}, "description": "ID of the document to be updated."}], "requestBody": {"required": true, "content": {"application/json": {"schema": {"type": "object", "properties": {"updated_data": {"type": "object", "additionalProperties": {"type": "string"}, "description": "New data to update the document with."}}, "required": ["updated_data"]}}}}, "responses": {"200": {"description": "Document updated successfully.", "content": {"application/json": {"schema": {"type": "object", "properties": {"document_id": {"type": "string", "description": "ID of the updated document."}}}}}}}}

Endpoint: GET /properties
Specification:
{"summary": "Retrieve All Properties", "description": "Fetch the list of all available property advertisements in the system.", "responses": {"200": {"description": "List of property advertisements retrieved successfully.", "content": {"application/json": {"schema": {"type": "array", "items": {"$ref": "#/components/schemas/Property"}}}}}}}
